export function buildTwins(authIds: Record<string, string>) {
  return TWINS.map((t) => ({
    ...t,
    auth_user_id: authIds[t.email] ?? null,
    computed_fits: (SEED_FITS[t.id] ?? []) as FitRecord[],
  }));
}

